        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DESCRIPTION&quot; title=&quot;Les dons&quot;&gt;format&lt;/a&gt;&lt;/li&gt;
        &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#TYPES&quot; title=&quot;Les dons&quot;&gt;types de dons&lt;/a&gt;&lt;/li&gt;
    &lt;/ul&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;script&gt;
$(function () {
  $(&quot;tr.donpr&#233;requis0, tr.donpr&#233;requis1, tr.donpr&#233;requis2&quot;).hide();
  $(&quot;tr.donprincipal&quot;).bind(&quot;click&quot;, togglePrereq);
  $(&quot;tr.donpr&#233;requis0&quot;).bind(&quot;click&quot;, togglePrereq0);
  $(&quot;tr.donpr&#233;requis1&quot;).bind(&quot;click&quot;, togglePrereq1);
  $(&quot;tr.donprincipal&quot;).each(addPrereqIconIfNeeded);
  $(&quot;tr.donpr&#233;requis0&quot;).each(addPrereqIconIfNeeded0);
  $(&quot;tr.donpr&#233;requis1&quot;).each(addPrereqIconIfNeeded1);
  $(&quot;tr.donpr&#233;requis2&quot;).each(addPrereqIconIfNeeded2);
});
function togglePrereq() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis0&quot;) || node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq0() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis1&quot;) || node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      if (node.hasClass(&quot;donpr&#233;requis2&quot;)) {
            node.toggle();
      };
      node = node.next();
    }
}
function togglePrereq1() {
    let nodeImg = $(this).find(&quot;img&quot;);
      if (nodeImg.attr(&quot;src&quot;) == &quot;/Forum/themes/v2/sort_down.gif&quot;) {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_up.gif&quot;);
      } else {
            nodeImg.attr(&quot;src&quot;, &quot;/Forum/themes/v2/sort_down.gif&quot;);
      };
    let node = $(this).next();
    while (node.length &gt; 0 &amp;&amp; node.hasClass(&quot;donpr&#233;requis2&quot;)) {
      node.toggle();
      node = node.next();
    }
}
function addPrereqIconIfNeeded() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded0() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
}
function addPrereqIconIfNeeded1() {
	let next = $(this).next();
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis2&quot;)) {
	  let icon = document.createElement(&quot;img&quot;);
	  icon.src = &quot;/Forum/themes/v2/sort_down.gif&quot;;
	  icon.style = &quot;float:right;margin-top: 3px;&quot;;
	  icon.title = &quot;Cliquez pour afficher les dons qui d&#233;coulent de celui-ci.&quot;;
	  $(this).children(&quot;td&quot;).first().append($(icon));
	}
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
function addPrereqIconIfNeeded2() {
	if (next.length &gt; 0 &amp;&amp; next.hasClass(&quot;donpr&#233;requis0&quot;) || next.hasClass(&quot;donpr&#233;requis1&quot;)) {
	  $(this).children(&quot;td&quot;).css(&quot;border-bottom&quot;, &quot;1px solid black&quot;);
	}
}
&lt;/script&gt;Les &lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html&quot; title=&quot;Le lutteur&quot;&gt;lutteurs&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerriers&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistoliers&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteurs&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;pr&#234;tres combattants&lt;/a&gt; peuvent choisir des dons de combat comme dons suppl&#233;mentaires. Les autres classes peuvent prendre des dons de combat &#224; condition de remplir les conditions requises.&lt;br /&gt;&lt;br /&gt;&lt;i&gt;Les dons marqu&#233;s d&#39;un ast&#233;risque (*) sont des dons de combat.&lt;/i&gt;
&lt;table CLASS=&quot;tablo centre toutgauche&quot;&gt;&lt;caption&gt;Tableau r&#233;capitulatif des dons de combat&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Dons&lt;/td&gt;&lt;td WIDTH=&quot;3%&quot;&gt;Src&lt;/td&gt;&lt;td WIDTH=&quot;30%&quot;&gt;Conditions&lt;/td&gt;&lt;td WIDTH=&quot;37%&quot;&gt;Avantages&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#192;-Terre-&#192;-Cheval.html&quot; title=&quot;&#192; terre &#224; cheval&quot;&gt;&#192; terre &#224; cheval&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-(Guerrier).html&quot; title=&quot;Dragon&quot;&gt;bond du lancier&lt;/a&gt;, 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;, 11 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;&#201;quitation.html&quot; title=&quot;&#201;quitation&quot;&gt;&#201;quitation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage remonte en selle par une action rapide s&#39;il r&#233;ussit un test d&#39;Acrobaties&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobate-Rus&#233;.html&quot; title=&quot;Acrobate rus&#233;&quot;&gt;Acrobate rus&#233;&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esquive.html&quot; title=&quot;Esquive&quot;&gt;Esquive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Souplesse-Du-Serpent.html&quot; title=&quot;Souplesse du serpent&quot;&gt;Souplesse du serpent&lt;/a&gt;, 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage gagne un bonus aux jets d&#39;attaque au corps &#224; corps quand il utilise Acrobaties pour &#233;viter des attaques d&#39;opportunit&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-De-La-Matraque.html&quot; title=&quot;Adepte de la matraque&quot;&gt;Adepte de la matraque&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Attaquesournoise.html&quot; title=&quot;attaque sournoise&quot;&gt;Attaque sournoise&lt;/a&gt; +1d6&lt;/td&gt;&lt;td&gt;Bonus de d&#233;g&#226;ts aux attaques non l&#233;tales&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;alt donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-De-La-Matraque.html&quot; title=&quot;Ma&#238;tre de la matraque&quot;&gt;Ma&#238;tre de la matraque&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Attaque sournoise +3d6, Adepte de la matraque&lt;/td&gt;&lt;td&gt;Double les d&#233;g&#226;ts d&#39;attaque sournoise en cas de d&#233;g&#226;ts non l&#233;taux&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier alt donprincipal&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Du-Filet.html&quot; title=&quot;Adepte du filet&quot;&gt;Adepte du filet&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AG&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maniement-Dune-Arme-Exotique.html&quot; title=&quot;Maniement d&amp;#39;une arme exotique&quot;&gt;Maniement d&#39;une arme exotique&lt;/a&gt; (filet), &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1&lt;/td&gt;&lt;td&gt;Consid&#232;re le filet comme une arme &#224; une main&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;donpr&#233;requis0&quot;&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Filet-Et-Trident.html&quot; title=&quot;Filet et trident&quot;&gt;Filet et trident&